refs=[1,2,1,3,1,2]
policy='FIFO'
capacity=2
resident=[]
faults=0
for page in refs:
    if page in resident:
        if policy=='LRU':
            resident.remove(page)
            resident.append(page)
    else:
        faults+=1
        if len(resident)==capacity:
            resident.pop(0)
        resident.append(page)
print(faults)

